def two_sum(nums, target)
  seen = {}
  nums.each_with_index do |n, i|
    return [seen[target - n], i] if seen.key?(target - n)
    seen[n] = i
  end
  [-1, -1]
end

puts two_sum([2, 7, 11, 15], 9).join(" ")

words = %w[eat tea tan ate nat bat]
groups = words.group_by { |w| w.chars.sort.join }.values
groups.map { |g| g.sort.join(",") }.sort.each { |line| puts line }
